+package com.oracle.jipher.internal.spi;
+
+import java.security.spec.AlgorithmParameterSpec;
+import javax.crypto.SecretKey;
+
+import org.junit.Test;
+
+import com.oracle.jipher.internal.openssl.MdAlg;
+
+import static org.junit.Assert.assertArrayEquals;
+import static org.junit.Assert.assertEquals;
+import static org.junit.Assert.fail;
+
+public class HkdfTest {
+
+    @Test
+    public void deriveKeyClearsDerivedData() throws Exception {
+        byte[] derivedData = new byte[] {1, 2, 3, 4, 5};
+        byte[] expectedKey = derivedData.clone();
+        Hkdf hkdf = new Hkdf(MdAlg.SHA256, 32, null) {
+            @Override
+            protected byte[] engineDeriveData(AlgorithmParameterSpec derivationSpec) {
+                return derivedData;
+            }
+        };
+
+        SecretKey key = hkdf.engineDeriveKey("AES", null);
+
+        assertArrayEquals(new byte[derivedData.length], derivedData);
+        assertEquals("AES", key.getAlgorithm());
+        assertArrayEquals(expectedKey, key.getEncoded());
+    }
+
+    @Test
+    public void deriveKeyClearsDerivedDataNeg() throws Exception {
+        byte[] derivedData = new byte[] {1, 2, 3, 4, 5};
+        Hkdf hkdf = new Hkdf(MdAlg.SHA256, 32, null) {
+            @Override
+            protected byte[] engineDeriveData(AlgorithmParameterSpec derivationSpec) {
+                return derivedData;
+            }
+        };
+
+        try {
+            hkdf.engineDeriveKey(null, null);
+            fail("Expected IllegalArgumentException");
+        } catch (IllegalArgumentException expected) {
+            // Expected from SecretKeySpec after engineDeriveData returns derivedData.
+        }
+
+        assertArrayEquals(new byte[derivedData.length], derivedData);
+    }
+}
